import {regionArt} from './expansion-cinema-content.js?v=5.41';
/** Developer practice UI. The caller owns the isolated game session and fixture creation. */
export function mountDevPortal({chapters,crew,recommend,briefFor=()=>null,onLaunch,onOpen=()=>{},onClose=()=>{}}){
 const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 const room=el('dialog');room.id='dev-portal';room.setAttribute('aria-labelledby','dev-portal-title');
 const shell=el('div');shell.className='dev-portal-shell';const head=el('header'),title=el('div');title.append(el('small','ASH & AETHER · DEVELOPMENT'),Object.assign(el('h2','Choose a chapter to test'),{id:'dev-portal-title'}));
 const close=el('button','Return to test');close.type='button';close.onclick=()=>api.close();head.append(title,close);shell.append(head,el('p','Practice sessions have their own crew and supplies. Your ordinary journey stays in its original tab. Reloading starts a fresh test.'));
 const content=el('div');content.className='dev-portal-content';const list=el('nav');list.className='dev-chapters';list.setAttribute('aria-label','Chapter selection');const details=el('section');details.className='dev-chapter-detail';content.append(list,details);shell.append(content);room.append(shell);document.body.append(room);
 let chapter=1,started=false,busy=false,selected=recommend(0),returnFocus=null;
 const selects=[];
 function selectParty(index,value){
  const next=Number(value),previous=selected[index],other=selected.indexOf(next);selected[index]=next;if(other>=0&&other!==index)selected[other]=previous;
  for(let i=0;i<selects.length;i++)selects[i].value=String(selected[i]);
 }
 function paint(){
  const entry=chapters.find(x=>x.chapter===chapter)||chapters[0],brief=briefFor(chapter);details.replaceChildren();selects.length=0;
  details.append(el('small','CHAPTER '+chapter+' / 24'),el('h3',entry.name),el('p',entry.bossName+' · prepared crew level '+entry.level));
  const image=el('img');image.src=new URL('../cinema/expanded/art/'+(chapter<=8?'guardian-'+chapter+'-0.webp':regionArt(chapter)),import.meta.url);image.alt='';image.className='dev-boss-art';image.onerror=()=>image.remove();details.append(image);
  if(brief){const p=el('p',brief.summary||brief.counterplay||brief.strategy||'Read the warning, answer the pattern, then use the recovery window.');p.className='dev-boss-brief';details.append(p);}
  const field=el('fieldset');field.append(el('legend','Test crew'));
  for(let i=0;i<3;i++){const label=el('label',['Lead character','Second crew member','Third crew member'][i]),select=el('select');select.setAttribute('aria-label',label.textContent);for(let id=0;id<crew.length;id++){const option=el('option',crew[id].name);option.value=String(id);select.append(option);}select.value=String(selected[i]);select.onchange=()=>selectParty(i,select.value);label.append(select);field.append(label);selects.push(select);}details.append(field);
  const branchLabel=el('label','Prior story choices '),branch=el('select');branch.setAttribute('aria-label','Prior story choices');branch.append(Object.assign(el('option','First choices'),{value:'0'}),Object.assign(el('option','Alternate choices'),{value:'1'}));branchLabel.append(branch);details.append(branchLabel);
  if(chapter===4){const focus=el('p','Chapel playtest: hear both accounts, trace the return, isolate and drain it, recover a tongue, test the answer, prepare for the Herald, then return to see what changed. Target session: 20–30 minutes; actual duration is recorded during play.');focus.className='dev-boss-brief';details.append(focus);}
  const note=el('p','A finite supply kit, learned techniques and earlier chapter rewards are prepared for this point. You can change equipment through Crew setup.');note.className='dev-kit-note';details.append(note);
  const error=el('p');error.className='dev-error';error.setAttribute('role','status');details.append(error);
  const actions=el('div');actions.className='dev-launch-actions';for(const [stage,text]of [...(chapter===4?[['chapel','Play the Chapel investigation']]:[]),['systems','Try the combined content'],['arrival','Explore this chapter'],['boss','Test the guardian']]){const b=el('button',text);b.type='button';b.onclick=async()=>{if(busy)return;busy=true;for(const item of actions.children)item.disabled=true;error.textContent='Preparing this chapter…';try{await onLaunch({chapter,stage:['chapel','systems'].includes(stage)?'arrival':stage,focus:stage==='chapel'?'chapel':stage==='systems'?'reconciliation':null,lead:selected[0],party:[...selected],branch:Number(branch.value)});started=true;busy=false;api.close();}catch(e){error.textContent=e?.message||'This test could not be prepared.';}finally{busy=false;for(const item of actions.children)item.disabled=false;}};actions.append(b);}details.append(actions);
  const ordinary=el('a','Open your ordinary journey');const url=new URL(location.href);url.searchParams.delete('dev');ordinary.href=url.href;ordinary.target='_blank';ordinary.rel='noopener';const motion=el('a','Movement studio · test every character');motion.href=new URL('./qa/motion.html?v=5.38',import.meta.url).href;motion.target='_blank';motion.rel='noopener';const authored=el('a','Authored animation review · Sable, Herald & Moonveil');authored.href=new URL('./qa/authored-motion.html?v=5.38',import.meta.url).href;authored.target='_blank';authored.rel='noopener';const scenery=el('a','3D environment studio · explore 167 places');scenery.href=new URL('./qa/composition.html?v=5.41',import.meta.url).href;scenery.target='_blank';scenery.rel='noopener';const collection=el('a','Scenery collection · painted props & materials');collection.href=new URL('./qa/environment-art-v17.html?v=5.41',import.meta.url).href;collection.target='_blank';collection.rel='noopener';const collection2=el('a','Environment collection II · rooms, roofs & old trees');collection2.href=new URL('./qa/environment-art-v19.html?v=5.41',import.meta.url).href;collection2.target='_blank';collection2.rel='noopener';details.append(ordinary,el('br'),scenery,el('br'),collection2,el('br'),collection,el('br'),motion,el('br'),authored);close.hidden=!started;
 }
 for(const entry of chapters){const b=el('button'),number=el('small',String(entry.chapter).padStart(2,'0')),name=el('strong',entry.name);b.append(number,name);b.type='button';b.dataset.chapter=String(entry.chapter);b.onclick=()=>{chapter=entry.chapter;for(const button of list.children)button.setAttribute('aria-pressed',String(button===b));paint();};b.setAttribute('aria-pressed',String(entry.chapter===chapter));list.append(b);}
 const api={open(){returnFocus=document.activeElement;onOpen();paint();if(!room.open)room.showModal();list.querySelector('[aria-pressed="true"]')?.focus();},close(){if(!started||busy)return;room.close();onClose();returnFocus?.isConnected&&returnFocus.focus();},destroy(){room.remove();}};
 room.addEventListener('keydown',e=>e.stopPropagation());room.addEventListener('keyup',e=>e.stopPropagation());
 room.addEventListener('cancel',e=>{e.preventDefault();api.close();});return api;
}
